import sys

def can_partition(A, B, C):
    total_sum = A * 1 + B * 2 + C * 3
    if total_sum % 2 != 0:
        return "NO"
    target = total_sum // 2

    dp = [False] * (target + 1)
    dp[0] = True

    for _ in range(A):
        for j in range(target, 0, -1):
            if j >= 1 and dp[j - 1]:
                dp[j] = True

    for _ in range(B):
        for j in range(target, 0, -1):
           	if j >= 2 and dp[j - 2]:
                dp[j] = True

    for _ in range(C):
        for j in range(target, 0, -1):
           if j >= 3 and dp[j - 3]:
                dp[j] = True

    return "YES" if dp[target] else "NO"

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        A = int(input[index])
        B = int(input[index + 1])
        C = int(input[index + 2])
        index += 3
        results.append(can_partition(A, B, C))
    print("\n".join(results))

if __name__ == "__main__":
    main()
